const fs=require('node:fs'),path=require('node:path');
const {decisions,personas,pages,transitions}=require('./model.cjs');
const dir=__dirname;
const table=(h,rows)=>'| '+h.join(' | ')+' |\n| '+h.map(()=> '---').join(' | ')+' |\n'+rows.map(r=>'| '+r.map(x=>String(x??'').replaceAll('|',' / ').replaceAll('\n',' ')).join(' | ')+' |').join('\n')+'\n';
const scope='**Phase 1 — proposed product design, not implemented behavior.** Prepared 5 November 2026. Deliverables are confined to docs/master-product-blueprint/. The approved user-facing visual design is a constraint. Existing source, UI, Firebase schemas/rules/functions, dependencies and data are unchanged. “Target” describes the reviewed-to-be product contract; numeric, retention and rollout choices marked policy approval required are proposals, not existing promises.\n\n';
function write(name,title,text){fs.writeFileSync(path.join(dir,name+'.md'),'# '+title+'\n\n'+scope+text+'\n\nImplementation requires the separate review requested by the user. Current-source comparisons and evidence limitations are in EXISTING_APPLICATION_GAP_ANALYSIS.md; target acceptance criteria must not be counted as executed tests.\n');}
fs.writeFileSync(path.join(dir,'target-decisions.json'),JSON.stringify(decisions.map(d=>({id:d[0],status:d[1],topic:d[2],decision:d[3],reason:d[4]})),null,2));
fs.writeFileSync(path.join(dir,'target-pages.json'),JSON.stringify(pages.map(p=>({id:p[0],name:p[1],route:p[2],audience:p[3],parent:p[4],data:p[5],controls:p[6],completion:p[7]})),null,2));
fs.writeFileSync(path.join(dir,'target-transitions.json'),JSON.stringify(transitions.map(t=>({id:t[0],name:t[1],actor:t[2],origin:t[3],inputs:t[4],authorization:t[5],operation:t[6],destination:t[7],writes:t[8],next:t[9],failure:t[10],returnBehavior:t[11]})),null,2));

write('PRODUCT_VISION_AND_DOMAIN_MODEL','Product vision and domain model',
 '## Product promise and completion\n\nNestMate helps a person find a suitable long-term place, suitable people to live with, or a suitable applicant for an actual available place. Its unit of value is a qualified housing conversation that leads to an informed, consensual offline housing decision, followed by an honest availability/search update. A browsing session, accepted request or successful message is an intermediate milestone; none proves a move-in. The product must reduce irrelevant discovery, unclear identity, unsolicited contact and stale inventory without making users surrender unnecessary personal data.\n\n'+
 '## Distinct domain concepts\n\n'+table(['Concept','Meaning','Never infer from'],[
 ['Account identity','One Auth UID and its private membership/moderation state.','A public display name, a role selector or a listing array index.'],
 ['Housing intent','Current find_room, team_up and/or have_room needs.','Permanent seeker/owner labels or another completed intent.'],
 ['Publisher/steward','Account authorized to manage the advertisement and applicant context.','Legal title to real estate. Current ownerId is a record-ownership field.'],
 ['Resident host','A person explicitly declaring residence at the associated available home.','Being an owner, a manager, identity-verified or accepted in chat.'],
 ['Accommodation','Physical room, shared space, entire flat or managed room/bed offer.','A person profile, vague role or estimated price.'],
 ['Communication consent','Pair-level permission to start/continue messages.','Shortlisting, comparing, sending an inquiry or selecting a potential tenant.'],
 ['Application/inquiry','A person’s expression of interest and answers for one listing/version.','All relationships with that publisher or a binding housing agreement.'],
 ['Identity review','Staff decision about specified private identity evidence.','Government authentication, ownership, residence, property inspection or guaranteed safety.'],
 ['Publication approval','Authorization to display a reviewed property version.','Identity approval alone.'],
 ['Availability','Publisher’s current declaration of advertised capacity.','An accepted connection, a shortlisted/selected applicant or someone’s private outcome.'],
 ['Housing outcome','Self-reported or mutually acknowledged team-up/housing progress.','Booking, lease signature, payment, tenancy proof or automatic occupancy.']])+
 '\n## Canonical relationship map\n\n```mermaid\nerDiagram\n  ACCOUNT ||--o{ INTENT : holds\n  ACCOUNT ||--o{ DISCLOSURE : consents\n  ACCOUNT ||--o{ LISTING : publishes\n  ACCOUNT ||--o{ RESIDENCE_DECLARATION : declares\n  LISTING ||--o{ RESIDENCE_DECLARATION : contextualizes\n  LISTING ||--o{ LISTING_VERSION : versions\n  LISTING ||--o{ APPLICATION : receives\n  ACCOUNT ||--o{ APPLICATION : submits\n  ACCOUNT ||--o{ PAIR_CONSENT : participates\n  PAIR_CONSENT ||--o| CONVERSATION : authorizes\n  CONVERSATION ||--o{ MESSAGE : contains\n  CONVERSATION ||--o{ CONTEXT_REFERENCE : discusses\n  LISTING ||--o{ CONTEXT_REFERENCE : referenced\n  ACCOUNT ||--o{ DIRECTIONAL_BLOCK : controls\n  ACCOUNT ||--o{ VERIFICATION_SUBMISSION : submits\n  VERIFICATION_SUBMISSION ||--o{ REVIEW_DECISION : receives\n  ACCOUNT ||--o{ BOOKMARK : saves\n  ACCOUNT ||--o{ HOUSING_OUTCOME : reports\n```\n\nThese are logical relationships and proposed ownership boundaries, not changes to Firestore collections. Compatibility adapters may retain current document paths during a separately approved implementation.\n\n'+
 '## Non-goals and constraints\n\nNo hotel nights, reservations, deposits/payments collected by NestMate, mandatory OTP, paid KYC provider, contract-signing workflow or group-management product is assumed. No promise of comprehensive fuzzy text search or globally ranked personalized matches without an implemented query/ranking service. Preserve the approved visuals; improve behavior and information meaning. Core onboarding should be progressive, not a fixed long questionnaire blocking anonymous property browsing.\n\n'+
 '## Definition of a completed journey\n\nRoom seeker: inspect real property → send qualified interest → receive consent → discuss/visit independently → declare housing found or continue searching. Team-up seeker: inspect a compatible consenting person → accepted conversation → mutual team-up acknowledgement → search accommodation together → optional housing declaration. Resident host: publish an actual spare room → review listing-specific applicants → communicate consensually → select/confirm offline arrangement → explicitly update capacity/filled status. Commercial publisher: publish physical inventory and handle qualified inquiries without appearing as a roommate. Staff: apply a justified, auditable case decision whose effects actually reach member/public views.\n\n'+
 '## Measurable success, with honest evidence\n\nMeasure query-to-qualified-detail, attributed-interest-to-accepted-consent, acknowledged-send delivery, publisher response, supported outcome declarations and inventory reconfirmation. Define denominator/cohort and retain null when no data exists. No synthetic growth charts, fabricated testimonials or presumed move-ins. Collect only necessary event IDs/context, not message text, contact details or ID documents in analytics.');

const capabilities=[
 ['Public accommodation browse/detail','Yes','Yes','Yes','Yes','Yes','Yes','Yes','Yes'],
 ['Member people directory','No identifiable cards','After eligible access; own publication optional','Resident hosts; team-up only if relevant intent chosen','Other opted-in team-up profiles','Eligible team-up/resident profiles','No commercial prospecting privilege','Capability needed for moderation access','Restricted according to own data/appeal policy'],
 ['Create a listing draft','Sign in first','Complete essentials first','If separately authorized publisher','If separately authorized publisher','Yes, explicit residence declaration','Yes, declared authorization/kind','No staff impersonation by default','No new advertisements'],
 ['Publish property','No','No','Publisher prerequisites','Publisher prerequisites','Separate content + identity prerequisites','Same separate publisher prerequisites','Only scoped review/approval command','No; existing public inventory restricted'],
 ['Appear as a human roommate','No','Complete intentional opt-in first','Not from find_room alone','Yes, opt-in/minimum card','Only with valid available linked home','Not from commercial role alone','No staff listing merely from membership','No new directory visibility'],
 ['Apply/request communication','No','Finish action-specific essentials','Yes','Yes','Yes','Yes for relevant housing context','Ordinary member identity requires ordinary consent','No new requests'],
 ['Send a message','No','No unsolicited chat','Accepted active pair only','Accepted active pair only','Accepted active pair only','Accepted active pair only','No unrestricted staff messaging identity','Existing history as allowed; no sending'],
 ['Read contacts/precise address','No','Own private data','Own data or explicit scoped peer grant','Same','Same','Same','Specific case/capability only','Own permitted data; no new disclosure grants'],
 ['Manage applications','No','No','Own submitted inquiry','Own submitted inquiry','Own listing’s applications','Own listing’s applications','Explicit scoped case capability','Read permitted history; no new publisher decisions'],
 ['Review private ID evidence','No','Own submission only','Own submission only','Own submission only','Own submission only','Own submission only','Identity-review capability, not Moderator alone','Own submission/history as allowed'],
 ['Grant staff membership','No','No','No','No','No','No','Administrator capability only','Never self-grant/reinstate'],
 ['Export/delete/account appeal','No account data','Own identity with required reauth','Own account','Own account','Own account','Own account','No mass export from ordinary moderation role','Own account/support subject to approved retention policy'],
];
write('USER_TYPES_AND_CAPABILITY_MATRIX','User types and capability matrix',
 '## User categories and purpose\n\n'+table(['Category','Goal','Required information','Relevant surfaces','Restrictions'],personas)+
 '\n## Capability matrix\n\n'+table(['Capability','Visitor','Incomplete member','find_room','team_up','Resident have_room','Nonresident/PG publisher','Staff','Restricted account'],capabilities)+
 '\n## Viewer-to-candidate rules\n\nA find_room member primarily sees physical places and the resident/publisher linked to a place. They can be a private applicant without appearing in the public people directory. A team_up member sees other eligible team-up people; resident hosts are relevant when find_room is also active. A resident host can review applicants and eligible disclosed people, but does not gain a raw directory of every pure room seeker. A commercial/PG publisher gets listing-specific applicant disclosures, not a general right to harvest member profiles. An individual who also holds team_up retains that ordinary personal capability independently of publishing. A member need not publish themselves to the directory merely to browse; sending a request explicitly discloses the necessary request/profile subset to the recipient.\n\n'+
 '## Minimum setup is action-specific\n\nBrowse: none. Bookmark: Auth identity. Send/request/application: active Auth plus shared essentials and the minimal recipient introduction disclosure. People publication: explicit opt-in, supported city/locality, declared eligible intent and a minimum reviewed display card; optional answers remain unknown and affect fit confidence, not fabricated defaults. Publishing: shared essentials, authorization-to-advertise declaration, complete property facts and the configured trust/review requirements. have_room badge: explicit residence + authorized listing link + actual available published capacity. Staff: trusted registry grant outside self-editable customer fields.\n\n'+
 '## Multi-intent examples\n\nA renter may seek a replacement home (find_room) while considering a future co-renter (team_up). A resident with one spare room may also team up for a later move; filling the room should remove the currently available have_room result, not erase team_up. A landlord may separately be a team-up seeker; only their personal opted-in intent produces a human roommate card. A resident advertising a leased room is the publisher/steward, not automatically the legal property owner. Valid authority/permission wording needs product review; no legal-title claim is inferred.\n\n'+
 '## Staff and account status\n\nContent moderation, identity review and staff administration are capability sets. Capabilities are enforced by authoritative services/rules and audited, not by hiding a button. A restricted account may still need security, support, export and erasure access; moderation must not accidentally remove all means to appeal or manage private data. Reinstatement re-evaluates current publication/consent prerequisites.');

write('COMPLETE_USER_EXPERIENCE_FLOW','Complete user experience flow',
 '## First interaction and alternate entry paths\n\n```mermaid\nflowchart TD\n  Entry[Landing or shared place/person link] --> Browse{Requested action}\n  Browse -->|Public place search| Feed[Typed query + physical cards]\n  Browse -->|Protected person or write| Auth[Sign in/register modal + safe return]\n  Feed --> Detail[Stable-ID place detail]\n  Detail -->|Read/gallery/share| Detail\n  Detail -->|Save or express interest| Auth\n  Auth --> Setup{Action prerequisites complete?}\n  Setup -->|No| Onboard[Progressive shared setup + intents + consent]\n  Setup -->|Yes| Resume[Review original action]\n  Onboard --> Resume\n  Resume --> Interest[Listing inquiry or person consent request]\n  Interest --> Decision{Recipient decision}\n  Decision -->|Decline/withdraw| Continue[Clear closed state + continue discovery]\n  Decision -->|Accept| Chat[Authorized conversation]\n  Chat --> Housing[Offline visit/discussion/decision]\n  Housing --> Outcome[Private declared housing/team-up outcome]\n  Outcome --> Remaining[Choose remaining intents; host confirms availability separately]\n```\n\nA shared detail link can bypass landing and query screens. Signing in never auto-sends an abandoned request, accepts a relationship or publishes a draft. A returning authenticated member can resume an authorized Saved record, conversation, draft or pending review by stable ID. Auth recovery returns to the same safe context without exposing another account’s draft.\n\n'+
 '## Complete transition ledger\n\nEach transition includes origin, visible inputs/actions, purpose, operation, destination, required data, authorization, persistence, next action, recovery and refresh/back behavior. The referenced page specification supplies its complete required content. No target acceptance statement below is an executed test.\n\n'+
 transitions.map(t=>'### '+t[0]+' — '+t[1]+'\n\n'+
 '**Actor / current location:** '+t[2]+'; '+t[3]+'.\n\n'+
 '**What the user sees and can do:** '+t[1]+' using '+t[4]+'\n\n'+
 '**Purpose and prerequisite:** '+t[5]+'\n\n'+
 '**Backend/business operation:** '+t[6]+'\n\n'+
 '**Destination/result:** '+t[7]+'\n\n'+
 '**Authoritative persistence:** '+t[8]+'\n\n'+
 '**Next available action:** '+t[9]+'\n\n'+
 '**Failure/cancellation:** '+t[10]+' No irreversible consequence follows from merely opening the view; cancellation before commit creates no successful business event. After acknowledgement, reversal uses its explicit domain command.\n\n'+
 '**Refresh/return:** '+t[11]+'\n\n'+
 '**Completion criterion:** The acknowledged result matches the authoritative read, the authorized next action is reachable, and every affected participant sees the corresponding state under CROSS_PAGE_CONSISTENCY_MAP.md.\n').join('\n')+
 '\n## Housing-specific completion\n\nA declined/expired request is a valid completed consent subjourney, followed by supported discovery. A member who finds housing elsewhere can stop selected searches without inventing an in-app match. A host who fills a room offline can mark it filled without choosing a NestMate applicant. Mutual team-up acknowledgement opens the next accommodation-search context but does not create a group lease or publish a fake property. Outcomes remain source-labelled and correctable. Follow-up is optional and rate-bounded; no unimplemented email is promised.');

write('INFORMATION_ARCHITECTURE','Information architecture',
 '## Navigation principles\n\nRetain the existing visible navigation and responsive treatment: Explore, Saved, Post, Messages, account/profile and contextual Connections/My listings/Notifications. Keep staff tools separate. Stable routes make current detail/overlay sections addressable without changing their visual layout. Do not build a new dashboard for every housing intent. Contextual deep routes open the same approved detail, wizard, table and drawer designs.\n\n'+
 '```mermaid\nflowchart LR\n  Home[/Landing/] --> Explore[Explore: All places / Rooms / Roommates / PG]\n  Explore --> Place[/places/:listingId]\n  Explore --> Person[/people/:uid]\n  Saved[Saved: Places / People] --> Place\n  Saved --> Person\n  Place --> Inquiry[Listing inquiry]\n  Person --> Consent[Pair request]\n  Inquiry --> Connections[Connections]\n  Consent --> Connections\n  Connections --> Messages[Messages/:conversationId]\n  Messages --> Place\n  Messages --> Person\n  Post[Post] --> Wizard[Listings/new or edit]\n  Listings[My listings] --> Wizard\n  Listings --> Applicants[Listings/:id/applicants]\n  Applicants --> Compare[Listing comparison]\n  Applicants --> Messages\n  Account[Profile] --> Prefs[Preferences + disclosure]\n  Account --> Identity[Manual verification]\n  Account --> Settings[Security / privacy / data / outcomes]\n  Staff[Admin] --> Queues[Scoped moderation/review/jobs]\n```\n\n'+
 '## Route and context contract\n\n'+table(['View','Target durable location','Preserved state'],[
 ['Explore categories','/explore?tab=all|rooms|roommates|pg&city=…&…','Typed city/localities/filter/sort; opaque continuation cursor; scroll restoration.'],
 ['Place/person detail','/places/:listingId; /people/:uid?contextListing=…','Entity kind/ID + safe authorized return descriptor; no raw sensitive criteria in URL.'],
 ['Member resume views','/saved?tab=…; /connections?tab=…; /notifications','Entity tab/status filters; own scope; target references by ID.'],
 ['Conversation','/messages/:conversationId','Paged history/read cursor and context references; draft account-scoped.'],
 ['Publisher work','/listings; /listings/new; /listings/:id/edit|applicants|compare','Owned draft/review/application IDs and version; no comparison by unstable indices.'],
 ['Shared setup/account','/onboarding?returnTo=…; /profile?section=…','Saved progress; safe return ID; explicit public/private preview scope.'],
 ['Staff','/admin?section=…&recordType=…&record=…','Capability-authorized selected record and pagination; no sensitive document URL in query.'],
 ['Informational destinations','/help /safety /privacy /terms /about /how-it-works','Actual reviewed content and origin context; no wildcard substitution.']])+
 '\n## Back, refresh and aliases\n\nOpening a detail pushes history and retains an allowlisted origin query/scroll descriptor; closing returns there, not a guessed default. Switching a filter replaces the current query and invalidates only its cursor; explicit section navigation pushes a new entry. Browser Back closes a URL-addressed overlay/detail before leaving its parent. Refresh loads the target by ID without the old feed. Sensitive forms retain only account-owned safe drafts; credentials/ID bytes/precise addresses are not stored in URLs or shared browser storage.\n\nExisting /explore?room=id links receive a compatible stable-detail resolution. Current eight routes remain valid entry points. Absent legacy /login, /chat and /owner-dashboard need explicit reviewed redirects only where their meaning is unambiguous; unknown paths show a useful not-found state rather than disguising an error as home. Auth redirects reject external/unsafe return destinations. No active request is automatically replayed after authentication.\n\n## Consolidation and reachability\n\nKeep one visible staff console and one canonical service contract; merge the embedded legacy Explore admin surface only after parity is characterized. Preserve distinct Saved entity tabs, listing applicants and pair Connections because their purposes differ. Informational/consent content belongs near the action as well as at its real destination. Incomplete optional controls are explicitly disabled or omitted until a complete lifecycle exists, not made clickable merely to produce a toast.');

const discovery=[
 ['All listings','Published available physical room/flat/managed inventory.','Human profiles, drafts/rejected/filled/expired or restricted-publisher records.','Discriminated listingId/kind, locality, honest photo state, price+unit, availability, scoped trust and freshness.','Supported city/locality/type/unit/rent/availability filters; newest or unit-scoped rent order.','/places/:listingId; context retained on return.'],
 ['Rooms and flats','Private/shared rooms and entire flats, with BHK separate from room type.','People, fabricated spare rooms, PG beds hidden as an ordinary full flat.','Actual offered unit and share; declared included charges/deposit; resident relationship only when explicit.','Room type, BHK, furnishing, supported amenities/rules and move-in; query-backed predicates.','Same canonical place detail; related publisher/resident UID resolved separately.'],
 ['Roommates','Opted-in team_up people and genuine available have_room resident profiles.','find_room-only members, nonresident commercial advertisers, staff-only identities, restricted/inactive/opted-out or invalid-host-only cards.','UID, explicit active intent badge, consented area/budget/lifestyle, evidence/unknown fit, related available listing only if valid.','Supported geography/preferences; discoverable cohort; no invented compatibility for incomplete viewers.','/people/:uid; public card and relationship projection use explicit access scopes.'],
 ['PG and coliving','Managed accommodation with real per-bed/per-room options and declared available capacity.','Synthetic one-bed options, implied nightly bookings or fabricated owner-roommate fit.','Kind, monthly price/unit, actual deposit/fees, managed amenities/rules, availability and publisher trust meaning.','City/locality, managed type, pricing unit, capacity and supported house conditions.','/places/:listingId renders managed fields without inventing separate entity identity.'],
];
write('DISCOVERY_AND_LISTING_WORKFLOW','Discovery and listing workflow',
 '## Section contracts\n\n'+table(['Section','Belongs here','Must not appear','Card evidence','Filters/sort','Detail/return'],discovery)+
 '\n## Search and pagination\n\nLanding, city cards and in-app filters serialize one typed query: supported city ID, locality IDs/text contract, entity kind, pricing unit/currency, optional rent bounds, move-in constraint and supported property/member predicates. City never becomes an unlabelled locality substring. Define exact/prefix/token semantics and unsupported-query feedback. Apply supported predicates before cursor pagination; arbitrary loaded-card filtering is not advertised as a complete market search. Server query scope and result completeness are displayed truthfully.\n\nUse stable order plus ID tie-breaker and opaque cursor carrying query/ranking version. A filter/sort/city change creates a new query key and invalidates the old cursor; late responses cannot replace it. Budget exhaustion during sparse eligibility scanning must preserve a valid continuation, not claim the database is empty. Supporting resident-listing lookups must fit the whole-operation read budget. Deduplicate by entity kind+ID. Live head changes signal new/changed results without reordering the user’s current scroll unexpectedly.\n\nNewest and same-unit rent orders have a dataset-wide contract over the supported query. Best match is not a synonym for arbitrary loaded sorting. Under D14 a bounded suggestion cohort is labelled explicitly, with its ranking model/version, known factors and missing evidence; it must not claim a global optimum. Missing preference is unknown, and a genuine computed zero remains zero. Do not replace it with an attractive baseline.\n\n## Empty/error states\n\nDistinguish no inventory in a supported city, no results for current valid filters, incomplete viewer setup for personalized suggestions, directory opt-out/no eligible candidate, temporary permission/network failure and exhausted versus continuation-available scan. Offer relevant clear-filter/change-city/complete-setup/retry actions. Never substitute verified stock listings after an empty or failed request. No “seen everything” statement unless the authoritative query is exhausted.\n\n## Property listing lifecycle journey\n\nPublisher Post → action-specific auth/setup → existing/new private draft → supported photos → kind/location → price/deposit/unit/capacity/move-in → explicit publisher/residence declarations → amenities/rules/questions → preview → Save draft or Submit for review. “Close” and “Save draft” have different persistence contracts. Required questions are validated before listing-specific inquiry submission; answers are private to applicant/publisher/scoped moderation, not public listing fields.\n\nSubmit acknowledges a review submission, never a public booking/publication. Content review and identity review are separate. Approved eligible availability produces the public version. Material edits create a new review version; the previous public version is preserved or paused under an explicit field-change policy. Owner pause/filled/reconfirm are separate availability commands. Filled/offline-arranged inventory can be reopened only after current publication, authorization, account and freshness checks. Shared links show the real inactive state where disclosure is allowed.\n\n## Public information and privacy\n\nPublic detail shows actual locality/approximate area, actual price/deposit/charges/unit, declared amenities/conditions, photos with functional missing/error fallback, current capacity/available date, update/freshness context, publisher identity subset and narrowly worded trust labels. Exact unit address and contact details remain private until explicitly shared. Approximate coordinates, if a map is later retained, must be labelled approximate; a UID-derived offset is not a real property location.');

const relationships=[
 ['Listing → publisher','listingId → publisherUid (current ownerId is record stewardship)','Published publisher display subset; authorized management scope for owner.','P09 contextual publisher view; no automatic resident/roommate label.','Missing/inactive publisher suppresses new public advertising; authorized history explains unavailable publisher.'],
 ['Listing → resident host','listingId + residence declaration UID/version','Explicit residence and listing publication/availability evidence.','P09 resident profile linked back to the actual offered room.','No valid current available link → no have_room availability badge; preserve other valid intents.'],
 ['Person → available place','UID → authorized associated listing IDs','Only published available related listings; verify stewardship/resident relation.','P08 by listingId, not a cached D index.','Unavailable listing removed from new host offer; contextual history retains honest status.'],
 ['Saved → entity','ownerUid + entityType + entityId','Own bookmark plus independent authorized projection read.','P08/P09; neutral tombstone if access lost.','Never show inaccessible raw data; allow removing stale bookmark and retrying transient errors.'],
 ['Application → listing/applicant','applicationId → listingId, applicantUid, publisherUid, listing version','Applicant/publisher/scoped staff; answer snapshot and separate stage.','P16 or applicant’s private status/context.','Listing inactive closes new submission; existing application retains policy-approved private status/history.'],
 ['Pair request → people/context','requestId/version → two UIDs; optional context reference','Participants; introduction subset disclosed at request submission.','P11/P09/P08 after scope authorization.','No numeric coercion or disclosure from a forged context parameter; expired/deleted targets show generic unavailable.'],
 ['Conversation → pair','conversationId → pair key and participants','Participant history scope; live consent/active accounts for sending.','P12; P09 header resolves counterpart UID.','Missing person does not become a fabricated profile or silently destroy all peer history.'],
 ['Message → attachment','messageId → authorized objectRef/version','Room participant + valid object scope; send eligibility rechecked on commit.','Safe image viewer inside the existing approved chat flow.','Deleted/expired object is explicitly unavailable; history text and retry state remain coherent.'],
 ['Verification → account/evidence','submissionId/version → subjectUid + private objectRef','Subject own status; reviewer explicit capability; no public evidence URL.','P19/P22; public trust receives only derived scoped status.','Missing evidence blocks a new approval; old reviewed version remains auditable under retention policy.'],
 ['Notification → target','eventId → typed target ID and action/version','Recipient plus reauthorization of referenced target/action.','Exact entity/context, not a guessed first room or generic user index.','Stale action becomes a status explanation; opening does not replay a completed command.'],
 ['Report → case target','caseId → typed listing/user/message ID + evidence scope','Reporter own acknowledgement; staff case capability; relevant private evidence only.','P22 typed inspector or safe acknowledgement.','Deleted content leaves policy-approved reference/tombstone, not a link to an unrelated listing.'],
 ['Outcome → involved context','outcomeId → actor + optional listing/application/pair IDs','Private actor declaration; mutual statement requires both acknowledgements.','P20 own follow-up and explicit remaining-intent choice.','Outcome correction does not forge availability or rewrite peer declarations.'],
];
write('ENTITY_AND_DETAIL_PAGE_RELATIONSHIPS','Entity and detail-page relationships',
 '## Identity and authorization contract\n\nEvery entity read takes a typed persisted reference and returns one of: authorized data with version/scope; known inactive/unavailable projection where permitted; generic not-found/unauthorized response where existence is private; or retryable service error. The UI never resolves a valid detail from an array position or concludes deletion because the current feed lacks an item. Query parameters provide context, not permission. A public listing’s publisher is not automatically a resident or a legally verified property owner.\n\n'+table(['Source → related entity','Authoritative IDs','Required data/permission','Navigation destination','Missing/inactive/deleted behavior'],relationships)+
 '\n## Detail loading sequence\n\n```mermaid\nsequenceDiagram\n  participant U as User\n  participant V as Detail view\n  participant G as Authorized entity gateway\n  participant E as Entity/projection store\n  participant R as Related reference resolver\n  U->>V: Open typed persisted ID\n  V->>G: ID + current auth + explicit context\n  G->>E: Authorize scope and read effective version\n  E-->>G: Data/version or permitted unavailable status\n  G-->>V: Field-allowlisted result\n  V->>R: Resolve authorized related IDs in a bounded batch\n  R-->>V: Related projections or scoped unavailable results\n  V-->>U: Real entity + current permitted actions\n```\n\n## Place-detail completion\n\nShow one canonical listing/version with actual facts, gallery, capacity/unit, costs, rules/questions, scoped trust and active/inactive status. Related publisher/resident actions resolve their own UIDs. Express interest passes the listing ID/version and questionnaire answers; an existing accepted pair skips another consent request but still creates the listing-specific inquiry record. Public anonymous users can inspect; protected actions open Auth with a safe return descriptor. Own unpublished detail is private, labelled preview and cannot be confused with the public version.\n\n## Person-detail completion\n\nResolve a public-directory card, listing-publisher subset, pending-request introduction or accepted-relationship projection according to the viewer’s actual authorization. Show which context is being viewed. No private quiz/contact/ID evidence is read and then merely hidden with CSS. A person’s find_room/team_up/have_room semantics remain explicit. Match explanation includes missing evidence; deleted/restricted accounts cannot continue sending merely because an old profile page is cached.');

write('INTERACTION_AND_COMMUNICATION_MODEL','Interaction and communication model',
 '## One coherent interaction model\n\nA person-only request asks for permission to communicate. A listing inquiry expresses interest in one property and may supply screening answers. If the pair has no consent, that inquiry creates/attaches one pending pair request in the same idempotent operation; it does not force the applicant through two equivalent approval gates. If consent is already accepted, the inquiry can open the existing conversation with a new listing context. The publisher still controls the application stage separately.\n\n'+
 '```mermaid\nflowchart TD\n  Action[Person Connect or listing Express interest] --> Kind{Listing context?}\n  Kind -->|Yes| App[Create/version application + answers]\n  Kind -->|No| Pair[Resolve pair state]\n  App --> Pair\n  Pair -->|Blocked/restricted| Stop[No request or send; safe explanation]\n  Pair -->|Pending reverse| Incoming[Offer explicit accept/decline]\n  Pair -->|No consent and recipient open| Request[One pending request + allowance event]\n  Pair -->|Accepted active pair| Chat[Open same authorized conversation]\n  Request --> Recipient[Recipient explicit decision]\n  Recipient -->|Accept| Chat\n  Recipient -->|Decline| Closed[Close request; no repeated sender reopen]\n  Chat --> Review[Application stage and housing outcome remain separate]\n```\n\n'+
 '## Action matrix\n\n'+table(['Action','Eligibility / transition','Other user sees','Failure/cancellation / next'],[
 ['Connect','Active complete sender; authorized target; no block; allowance; none→pending.','Minimal disclosed introduction and context; accept/decline.','Duplicate idempotent; reverse pending becomes Incoming; sender can withdraw.'],
 ['Express interest','Available listing + valid required answers; create application; create consent only if needed.','Listing/version/answers, consideration stage and separate communication request.','Listing changed → refresh answers/context; no new charge for an existing accepted pair.'],
 ['Accept/decline','Recipient of current pending version only.','Accepted Message or closed generic decline; private reason stays private.','Conflicting withdrawal/block returns actual state, not local success.'],
 ['Withdraw','Own pending request/inquiry, with explicit entity scope.','Closed scope without erasing an unrelated accepted relationship.','No blanket quota refund; show current accepted state on conflict.'],
 ['Message','Accepted active pair; current send authorization.','Persisted message with per-recipient delivery/read state.','Failed draft remains retryable by clientMessageId; no phantom conversation/message.'],
 ['Contact/address sharing','Data owner explicitly approves a specific disclosure to that peer.','Only the granted subset; public source remains private.','Revocation affects future reads; cannot promise recall of copied data.'],
 ['Block','Either person owns their directional block; overrides all pair contexts.','Generic restriction; no disclosure of blocker/reason or a block notification.','Idempotent server state; existing/new-room sends and attachments denied.'],
 ['Unblock','Only owner removes their block.','No automatic notification/accepted access; remaining peer block stays effective.','Fresh explicit consent required if all restrictions removed.'],
 ['Applicant shortlist/select','Publisher of specific listing/application.','Truthful consideration update where policy permits; no implied tenant contract.','No automatic communication acceptance, fill or occupancy.']])+
 '\n## Permission is evaluated at commit\n\nButtons derive from the same authoritative pair/application/account versions across cards, person detail, listing detail, Connections, Notifications and chat. The service rechecks active accounts, blocks, pending ownership and current consent on every sensitive commit. Private profile access and historical chat access are narrower/scoped reads; suspension/block denies new sends even in already-open rooms. Exact anonymous response and history-retention policy must avoid account-existence leaks and undocumented loss.\n\n## Notifications and quotas\n\nDurable domain events/outbox entries derive recipient notifications after the business commit. Delivery is tracked independently; failure to send a notification must not erase a committed request or charge twice. Notification opening reauthorizes the typed target; stale actions show current state. Only a new eligible outbound pair request consumes the approved allowance, atomically with its request ID/period. Existing accepted communication, retries, duplicate/reverse pending requests and opening a chat do not. The D05 numeric/renewal proposal requires policy approval and a reviewed legacy conversion.\n\n## Deliberately excluded mechanics\n\nNo automatic contact disclosure, unsolicited listing-owner chat exception, automatic filling from acceptance/selection, arbitrary resending after decline, “typing” or “email sent” claims without an implemented signal, or payment/booking confirmation is included. Optional typing/read-receipt disclosure can be added only with an enforceable privacy setting; the core send/read model does not depend on it.');

